public class Main {
    static class Edge {
        int to, cost;
        Edge(int to, int cost) {
            this.to = to;
            this.cost = cost;
        }
    }

    static class State implements Comparable<State> {
        long dist;
        int node, paved;
        State(long dist, int node, int paved) {
            this.dist = dist;
            this.node = node;
            this.paved = paved;
        }
        public int compareTo(State o) {
            return Long.compare(this.dist, o.dist);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        List<Edge>[] graph = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            graph[a].add(new Edge(b, c));
            graph[b].add(new Edge(a, c));
        }

        long[][] dist = new long[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dist[i], Long.MAX_VALUE);
        }
        dist[1][0] = 0;

        PriorityQueue<State> pq = new PriorityQueue<>();
        pq.offer(new State(0, 1, 0));

        while (!pq.isEmpty()) {
            State cur = pq.poll();

            if (cur.dist > dist[cur.node][cur.paved]) continue;

            for (Edge edge : graph[cur.node]) {
                // Don't pave
                long newDist = cur.dist + edge.cost;
                if (newDist < dist[edge.to][cur.paved]) {
                    dist[edge.to][cur.paved] = newDist;
                    pq.offer(new State(newDist, edge.to, cur.paved));
                }

                // Pave
                if (cur.paved < k && cur.dist < dist[edge.to][cur.paved + 1]) {
                    dist[edge.to][cur.paved + 1] = cur.dist;
                    pq.offer(new State(cur.dist, edge.to, cur.paved + 1));
                }
            }
        }

        long answer = Long.MAX_VALUE;
        for (int i = 0; i <= k; i++) {
            answer = Math.min(answer, dist[n][i]);
        }
        System.out.println(answer);
    }
}

