const ll INF = 1e18;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m, k;
    cin >> n >> m >> k;

    vector<vector<pair<int, int>>> graph(n + 1);
    for (int i = 0; i < m; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        graph[a].push_back({b, c});
        graph[b].push_back({a, c});
    }

    vector<vector<ll>> dist(n + 1, vector<ll>(k + 1, INF));
    dist[1][0] = 0;

    priority_queue<piii, vector<piii>, greater<piii>> pq;
    pq.push({0, {1, 0}});

    while (!pq.empty()) {
        ll d = pq.top().first;
        int node = pq.top().second.first;
        int paved = pq.top().second.second;
        pq.pop();

        if (d > dist[node][paved]) continue;

        for (auto& edge : graph[node]) {
            int next = edge.first;
            int cost = edge.second;

            // Don't pave
            ll newDist = d + cost;
            if (newDist < dist[next][paved]) {
                dist[next][paved] = newDist;
                pq.push({newDist, {next, paved}});
            }

            // Pave
            if (paved < k && d < dist[next][paved + 1]) {
                dist[next][paved + 1] = d;
                pq.push({d, {next, paved + 1}});
            }
        }
    }

    ll answer = INF;
    for (int i = 0; i <= k; i++) {
        answer = min(answer, dist[n][i]);
    }
    cout << answer << endl;

    return 0;
}

