        self.n = n
        self.tree = [0] * (4 * n)
        self.build(1, 1, n)

    def build(self, node, start, end):
        if start == end:
            self.tree[node] = 1
        else:
            mid = (start + end) // 2
            self.build(2 * node, start, mid)
            self.build(2 * node + 1, mid + 1, end)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def query(self, node, start, end, k):
        if start == end:
            return start

        mid = (start + end) // 2
        left_count = self.tree[2 * node]

        if k <= left_count:
            return self.query(2 * node, start, mid, k)
        else:
            return self.query(2 * node + 1, mid + 1, end, k - left_count)

    def update(self, node, start, end, idx):
        if start == end:
            self.tree[node] = 0
        else:
            mid = (start + end) // 2
            if idx <= mid:
                self.update(2 * node, start, mid, idx)
            else:
                self.update(2 * node + 1, mid + 1, end, idx)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

